// Asset metadata structures (tables are generated by tools/convert.py)
#pragma once
#include <nds.h>

typedef struct { u8 fmt, wlog, hlog, pad; u32 off; u32 size; } TexDef;
typedef struct { u8 tex, pad; u16 u, v, w, h; s16 dx, dy; } PartDef;
typedef struct { u16 first, count; } FrameDef;
typedef struct {
	const char *file;
	float scale;            // texels per drawn unit
	u16 nTex, nFrames, palCount, palOff;
	const TexDef *tex;
	const FrameDef *frames;
	const PartDef *parts;
} SheetDef;

// animated sprite frame (streamed into a VRAM slot)
typedef struct {
	u32 off;                // offset in the .bin file (after palette)
	u16 w, h, cw, pad;      // stored width (multiple of 4), height, real width
	float dx, dy;           // world offset of the top-left (scale and origin applied)
	float ww, wh;           // world size
} ChrFrame;

typedef struct {
	const char *name;
	float fps;
	u8 loop;
	float offx, offy;       // world offset added for this animation (-animOffset * scale)
	u16 nFrames;
	const u16 *frames;
} ChrAnim;

typedef struct {
	const char *file;
	float tscale;           // texels per world unit
	u8 slotWlog, slotHlog;
	float width, height;    // hitbox (first frame source size, unscaled)
	float gx, gy;           // globalOffset
	float camx, camy;       // cameraOffset
	float holdTime;
	u8 icon, isPlayer;
	u16 nFrames;
	const ChrFrame *frames;
	u16 nAnims;
	const ChrAnim *anims;
} ChrDef;

typedef struct { u8 x, y, w, h; s8 ox, oy; u8 adv; } Glyph;
typedef struct {
	const char *file;
	u8 wlog, hlog;
	u8 lineh, ascent;
	const Glyph *glyphs;    // chars 32..126
} FontDef;

// charts
typedef struct { float time, len; u8 dir; } NoteDef;
typedef struct { float time; u8 type, ease; s8 i0, i1; float f[4]; const char *s; } EventDef;
typedef struct { float time, bpm; } BpmChange;
typedef struct {
	const NoteDef *notes;
	u16 nNotes;
	float scale, spacing, pos, y;
	u8 visible;
} StrumDef;
typedef struct {
	StrumDef sl[2];
	const EventDef *events;
	u16 nEvents;
	const BpmChange *bpm;
	u8 nBpm;
	float speed;
	u8 beatsPerMeasure, stepsPerBeat;
} SongDef;

typedef struct {
	const SheetDef *sheet;
	const u8 *press[4];
	u8 nPress[4];
	const u8 *confirm[4];
	u8 nConfirm[4];
	float w0, h0;           // first atlas frame size (strum hitbox)
	float noteH;            // scroll note frame height
	u8 fStatic[4], fNote[4], fPress[4], fConfirm[4], fHold[4], fEnd[4];
} NoteSkin;
